import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {decide} from '/home/holo/line/tools/measure/engine_decision.ts';
const root='/tmp/engine-fixed-constraints-20261104',cells=JSON.parse(readFileSync('/home/holo/line/tools/parity/cells.json','utf8')).cells;
const runs=[];
for(const name of ['screen']){
 const result=JSON.parse(readFileSync(root+'/'+name+'/result.json','utf8'));
 assert(result.complete);assert.equal(result.samples.length,24);
 const pairs=Array.from({length:12},(_,round)=>{
  const a=result.samples.find((s:any)=>s.round===round&&s.arm===0),b=result.samples.find((s:any)=>s.round===round&&s.arm===1);
  for(const sample of [a,b])for(const m of sample.measurements){assert.equal(m.trackHash,cells[m.cell].trackHash);assert.equal(m.physicalFrames,cells[m.cell].physicalFrames);}
  return {base:a.nsPerFrame,candidate:b.nsPerFrame};
 });
 assert.deepEqual(result.decision,decide(pairs,result.protocol.threshold));
 runs.push({name,means:[pairs.reduce((n,p)=>n+p.base,0)/12,pairs.reduce((n,p)=>n+p.candidate,0)/12],decision:result.decision});
}
writeFileSync(root+'/audit.json',JSON.stringify({status:'PASS: decisions and exact work/output reproduced from raw pairs',runs},null,2)+'\n');
console.log(runs);

